def unknown_events(clean_events):
    return clean_events.filter(~known())


def delivered(known_events):
    return known_events.filter(F.col("event_type") == "delivered")


def in_flight(delivered):
    done = [r.shipment_id for r in delivered.select("shipment_id").collect()]
    return shipments.filter(~F.col("shipment_id").isin(done))


tasks = {
    "in_flight": (in_flight, ["delivered"]),
    "delivered": (delivered, ["known_events"]),
    "unknown_events": (unknown_events, ["clean_events"]),
    "known_events": (known_events, ["clean_events"]),
    "clean_events": (clean_events, []),
}
deps = {name: needs for name, (fn, needs) in tasks.items()}


def run_order(deps):
    order = []
    while len(order) < len(deps):
        ready = [t for t in deps if t not in order and all(d in order for d in deps[t])]
        if not ready:
            waiting = [t for t in deps if t not in order]
            raise ValueError("these tasks wait on each other: " + ", ".join(waiting))
        order += ready
    return order


STORE = "/tmp/pipeline"
shutil.rmtree(STORE, ignore_errors=True)
broken = {"delivered"}  # on the first run this task fails


def run(status):
    outputs = {}
    for name in run_order(deps):
        fn, needs = tasks[name]
        if status.get(name) == "ok":
            outputs[name] = spark.read.parquet(f"{STORE}/{name}")  # done before: reuse its saved output
            continue
        if any(status[d] != "ok" for d in needs):
            status[name] = "skipped"
            continue
        try:
            if name in broken:
                raise RuntimeError("the warehouse disk was full")
            fn(*[outputs[d] for d in needs]).write.mode("overwrite").parquet(f"{STORE}/{name}")
            outputs[name] = spark.read.parquet(f"{STORE}/{name}")
            status[name] = "ok"
            print("  ran", name)
        except Exception:
            status[name] = "failed"
    return outputs


status = {}
print("first run")
run(status)
print(status)

broken.clear()
print("rerun")
outputs = run(status)
print(status)
print(outputs["in_flight"].count(), "shipments in flight")
